import type { ExtensionManifest } from "./types";

const extension = (value: ExtensionManifest) => value;
const redis = extension({
  schemaVersion: 1,
  id: "redis",
  version: "1.0.0",
  kind: "capability",
  displayName: "Redis service and client",
  supportedLaunchStack: ">=2 <4",
  coverage: "complete",
  packages: { dependencies: { ioredis: "^5.4.0" } },
  environment: [
    {
      name: "REDIS_URL",
      description: "Redis connection URL",
      example: "redis://localhost:6379",
      required: true,
    },
  ],
  composeServices: {
    redis: {
      image: "redis:8-alpine",
      restart: "unless-stopped",
      ports: ["127.0.0.1:${LAUNCHSTACK_REDIS_PORT:-6379}:6379"],
      healthcheck: {
        test: ["CMD", "redis-cli", "ping"],
        interval: "5s",
        timeout: "3s",
        retries: 10,
      },
    },
  },
  files: [
    {
      path: "src/launchstack/capabilities/redis.ts",
      content: `import Redis from "ioredis";\nexport function createRedisClient(url = process.env.REDIS_URL): Redis { if (!url) throw new Error("REDIS_URL is required"); return new Redis(url, { lazyConnect: true, maxRetriesPerRequest: null, enableReadyCheck: true }); }\n`,
    },
  ],
});
const queue = extension({
  schemaVersion: 1,
  id: "queue",
  version: "1.0.0",
  kind: "capability",
  displayName: "BullMQ worker and queue",
  supportedLaunchStack: ">=2 <4",
  coverage: "complete",
  dependencies: ["redis"],
  packages: { dependencies: { bullmq: "^5.0.0" } },
  scripts: { worker: "tsx src/worker.ts" },
  environment: [
    {
      name: "QUEUE_PREFIX",
      description: "BullMQ key prefix",
      example: "launchstack",
    },
  ],
  files: [
    {
      path: "src/launchstack/capabilities/queue.ts",
      content: `import { Queue, type JobsOptions } from "bullmq";\nimport { createRedisClient } from "./redis";\nexport const DEFAULT_QUEUE_NAME = "launchstack-default";\nexport function createQueue<Data>(name = DEFAULT_QUEUE_NAME): Queue<Data> { if (!/^[a-zA-Z0-9:_-]{1,80}$/.test(name)) throw new Error("Invalid queue name"); return new Queue<Data>(name, { connection: createRedisClient(), prefix: process.env.QUEUE_PREFIX || undefined, defaultJobOptions: { attempts: 3, backoff: { type: "exponential", delay: 1000 }, removeOnComplete: 1000, removeOnFail: 5000 } satisfies JobsOptions }); }\n`,
    },
    {
      path: "src/worker.ts",
      content: `import { createServer } from "node:http";\nimport { Worker } from "bullmq";\nimport { createRedisClient } from "./launchstack/capabilities/redis";\nimport { DEFAULT_QUEUE_NAME } from "./launchstack/capabilities/queue";\nconst connection = createRedisClient();\nconst worker = new Worker(DEFAULT_QUEUE_NAME, async (job) => { console.info(JSON.stringify({ event: "job.processed", jobId: job.id, name: job.name })); return { processed: true }; }, { connection, prefix: process.env.QUEUE_PREFIX || undefined, concurrency: 4 });\nworker.on("failed", (job, error) => console.error(JSON.stringify({ event: "job.failed", jobId: job?.id, error: error.message })));\nlet workerReady = false;\nworker.on("ready", () => { workerReady = true; console.info(JSON.stringify({ event: "worker.ready", queue: DEFAULT_QUEUE_NAME })); });\nconst healthPort = Number(process.env.LAUNCHSTACK_WORKER_HEALTH_PORT ?? 0);\nconst healthServer = healthPort > 0 ? createServer((request, response) => { response.statusCode = request.url === "/healthz" && workerReady ? 200 : 503; response.end(); }).listen(healthPort, "127.0.0.1") : null;\nlet stopping = false;\nasync function shutdown(): Promise<void> { if (stopping) return; stopping = true; if (healthServer) await new Promise<void>((resolve) => healthServer.close(() => resolve())); await worker.close(); await connection.quit(); }\nprocess.once("SIGINT", () => { void shutdown().then(() => process.exit(0)); });\nprocess.once("SIGTERM", () => { void shutdown().then(() => process.exit(0)); });\n`,
    },
  ],
});
const oauth = extension({
  schemaVersion: 1,
  id: "oauth",
  version: "1.0.0",
  kind: "capability",
  coverage: "helper-only",
  displayName: "OAuth client helpers",
  supportedLaunchStack: ">=2 <4",
  environment: [
    {
      name: "OAUTH_CLIENT_ID",
      description: "OAuth client identifier",
      required: true,
    },
    {
      name: "OAUTH_CLIENT_SECRET",
      description: "OAuth client secret",
      required: true,
      secret: true,
    },
    {
      name: "OAUTH_REDIRECT_URI",
      description: "OAuth callback URL",
      example: "http://localhost:3000/api/auth/callback",
      required: true,
    },
  ],
  files: [
    {
      path: "src/launchstack/capabilities/oauth.ts",
      content: `export function buildAuthorizationUrl(input: { authorizationEndpoint: string; state: string; scope: string[] }): string { if (input.state.length < 16) throw new Error("OAuth state must contain at least 16 characters"); const clientId = process.env.OAUTH_CLIENT_ID; const redirectUri = process.env.OAUTH_REDIRECT_URI; if (!clientId || !redirectUri) throw new Error("OAuth client configuration is incomplete"); const url = new URL(input.authorizationEndpoint); url.searchParams.set("response_type", "code"); url.searchParams.set("client_id", clientId); url.searchParams.set("redirect_uri", redirectUri); url.searchParams.set("scope", input.scope.join(" ")); url.searchParams.set("state", input.state); return url.toString(); }\n`,
    },
  ],
});
