const cron = extension({
  schemaVersion: 1,
  id: "cron",
  version: "1.0.0",
  kind: "capability",
  coverage: "complete",
  displayName: "Scheduled worker",
  supportedLaunchStack: ">=2 <4",
  scripts: { scheduler: "tsx src/scheduler.ts" },
  files: [
    {
      path: "src/launchstack/capabilities/cron.ts",
      content: `export function scheduleInterval(task: () => Promise<void>, intervalMs: number, onError: (error: unknown) => void = console.error): () => void { if (!Number.isFinite(intervalMs) || intervalMs < 1000) throw new Error("intervalMs must be at least 1000"); let running = false; const timer = setInterval(() => { if (running) return; running = true; void task().catch(onError).finally(() => { running = false; }); }, intervalMs); return () => clearInterval(timer); }\n`,
    },
    {
      path: "src/scheduler.ts",
      content: `import { createServer } from "node:http";\nimport { scheduleInterval } from "./launchstack/capabilities/cron";\nconst intervalMs = Number(process.env.CRON_INTERVAL_MS ?? 60000);\nconst stop = scheduleInterval(async () => { console.info(JSON.stringify({ event: "schedule.tick", at: new Date().toISOString() })); }, intervalMs);\nlet schedulerReady = true;\nconsole.info(JSON.stringify({ event: "scheduler.ready", intervalMs }));\nconst healthPort = Number(process.env.LAUNCHSTACK_SCHEDULER_HEALTH_PORT ?? 0);\nconst healthServer = healthPort > 0 ? createServer((request, response) => { response.statusCode = request.url === "/healthz" && schedulerReady ? 200 : 503; response.end(); }).listen(healthPort, "127.0.0.1") : null;\nlet stopping = false;\nfunction shutdown(): void { if (stopping) return; stopping = true; stop(); if (healthServer) healthServer.close(() => process.exit(0)); else process.exit(0); }\nprocess.once("SIGINT", shutdown);\nprocess.once("SIGTERM", shutdown);\n`,
    },
  ],
});
const webhooks = extension({
  schemaVersion: 1,
  id: "webhooks",
  version: "1.0.0",
  kind: "capability",
  coverage: "helper-only",
  displayName: "Signed webhooks",
  supportedLaunchStack: ">=2 <4",
  environment: [
    {
      name: "WEBHOOK_SIGNING_SECRET",
      description: "Webhook HMAC secret",
      required: true,
      secret: true,
    },
  ],
  files: [
    {
      path: "src/launchstack/capabilities/webhooks.ts",
      content: `import { createHmac, timingSafeEqual } from "node:crypto";\nexport function verifyWebhookSignature(payload: string | Buffer, signature: string, secret = process.env.WEBHOOK_SIGNING_SECRET): boolean { if (!secret || !/^[a-f0-9]{64}$/i.test(signature)) return false; const expected = createHmac("sha256", secret).update(payload).digest(); const supplied = Buffer.from(signature, "hex"); return supplied.length === expected.length && timingSafeEqual(supplied, expected); }\n`,
    },
  ],
});

export const FIRST_PARTY_EXTENSIONS: Record<string, ExtensionManifest> =
  Object.fromEntries(
    [
      redis,
      queue,
      oauth,
      storage,
      observability,
      websocket,
      email,
      cron,
      webhooks,
    ].map((item) => [item.id, item]),
  );
export function listFirstPartyExtensions(): ExtensionManifest[] {
  return Object.values(FIRST_PARTY_EXTENSIONS).sort((left, right) =>
    left.id.localeCompare(right.id),
  );
}
